package com.zeptopluse.service; import com.zeptopluse.dto.*; import com.zeptopluse.entity.Customer; import com.zeptopluse.exception.*; import com.zeptopluse.mapper.CustomerMapper; import com.zeptopluse.repository.CustomerRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service @RequiredArgsConstructor public class CustomerService { private final CustomerRepository customers; private final CustomerMapper mapper; @Transactional public CustomerResponse create(CustomerRequest request){customers.findByPhone(request.phone()).ifPresent(x->{throw new ConflictException("A customer with this phone already exists");});Customer c=new Customer();c.setName(displayName(request.name()));c.setPhone(request.phone().trim());c.setEmail(blankToNull(request.email()));return mapper.toResponse(customers.save(c));} public CustomerResponse get(Long id){return mapper.toResponse(customers.findById(id).orElseThrow(()->new ResourceNotFoundException("Customer not found: "+id)));} private String displayName(String v){return v==null||v.isBlank()?"Guest Customer":v.trim();} private String blankToNull(String v){return v==null||v.isBlank()?null:v.trim();} }